# slug: (area keyword for title, [(q,a),...])  -- answers restate only what each column already says
FAQ={
"drunk-touch-complaint":("성범죄",[("술에 취해 기억이 안 나면 감경되나요?","성폭력처벌법은 음주로 인한 심신장애 상태의 성범죄에 감경 규정을 적용하지 않을 수 있도록 정하고 있어, 취해서 기억이 안 난다는 사정만으로 유리한 결과를 기대하기 어렵습니다."),("상대방에게 사과 메시지를 보내도 되나요?","보내지 않는 것이 좋습니다. 혐의를 인정한 증거로 제출될 수 있고, 원치 않는 연락은 2차 피해나 합의 강요로 비칠 수 있습니다."),("합의하면 사건이 끝나나요?","성범죄는 친고죄가 아니어서 합의해도 수사와 재판은 계속될 수 있습니다. 다만 합의는 처분과 양형에서 매우 중요하게 고려됩니다.")]),
"police-summons":("형사",[("출석 날짜를 바꿀 수 있나요?","네. 수사기관은 피의자와 일시·장소를 협의하도록 되어 있어 준비를 위한 일정 조율을 요청할 수 있습니다. 다만 정당한 이유 없이 계속 불응하면 체포영장 청구 등으로 이어질 수 있습니다."),("조사받을 때 변호사가 같이 들어갈 수 있나요?","피의자신문에 변호인이 참여하게 해 달라고 신청할 수 있습니다(형사소송법 제243조의2)."),("조서에 서명하기 전에 고칠 수 있나요?","조서를 읽어 보고 진술과 다르게 적힌 부분은 고쳐 달라고 요구할 수 있습니다. 서명한 뒤에는 내용을 뒤집기 매우 어렵습니다.")]),
"deposit-return":("부동산",[("보증금을 못 받았는데 먼저 이사해도 되나요?","보증금을 받지 못한 채 전출하면 대항력과 우선변제권을 잃을 수 있습니다. 이사 전에 임차권등기명령을 신청하고, 등기부에 기재된 것을 확인한 뒤 전출하세요."),("계약 만료 몇 달 전에 알려야 하나요?","임차인은 계약 기간이 끝나기 2개월 전까지 갱신하지 않겠다는 뜻을 알려야 합니다. 알리지 않으면 같은 조건으로 갱신된 것으로 볼 수 있습니다."),("소송하면 지연이자도 받을 수 있나요?","보증금반환청구소송에서는 소장 송달 다음 날부터 연 12%의 지연이자를 함께 청구할 수 있습니다.")]),
"online-defamation-discovery":("명예훼손",[("유튜브 익명 계정도 신원을 알아낼 수 있나요?","국내 민사소송을 낸 뒤 미국 연방법 제1782조에 따른 디스커버리 절차로 구글 등에 계정 정보 제출을 요구하는 방법이 있습니다."),("형사 고소만으로 디스커버리를 신청할 수 있나요?","형사 고소만을 위한 신청은 기각될 위험이 커서 실무에서는 민사소송을 기반으로 신청합니다."),("모욕죄는 언제까지 고소해야 하나요?","모욕죄는 친고죄로, 범인을 알게 된 날부터 6개월 안에 고소해야 합니다.")]),
"illegal-filming":("성범죄",[("불법촬영은 어떻게 처벌되나요?","성폭력처벌법 제14조에 따라 7년 이하 징역 또는 5천만 원 이하 벌금입니다. 불법촬영물을 소지·시청해도 3년 이하 징역 또는 3천만 원 이하 벌금으로 처벌됩니다."),("사진을 지우면 괜찮지 않나요?","포렌식으로 대부분 복구되고, 삭제 시도 자체가 불리한 정황이 됩니다."),("찍으려다 실패해도 처벌되나요?","네. 미수범도 처벌됩니다.")]),
"tongmaeum":("성범죄",[("통매음은 어떻게 처벌되나요?","성폭력처벌법 제13조에 따라 2년 이하 징역 또는 2천만 원 이하 벌금입니다."),("통매음도 신상정보 등록이 되나요?","유죄가 확정되면 원칙적으로 등록 대상이지만, 벌금형이 선고되면 등록 대상에서 제외됩니다."),("상대가 메시지를 안 읽었으면 괜찮나요?","상대가 볼 수 있는 상태가 되면 도달한 것으로 보아, 읽지 않았어도 성립할 수 있습니다.")]),
"minor-solicitation":("성범죄",[("아동·청소년 성매수는 어떻게 처벌되나요?","아청법 제13조 제1항에 따라 1년 이상 10년 이하 징역 또는 2천만 원 이상 5천만 원 이하 벌금이며, 상대가 16세 미만이면 2분의 1까지 가중됩니다."),("상대가 동의했는데도 처벌되나요?","19세 이상인 사람이 16세 미만과 성관계를 하면 동의나 대가와 관계없이 미성년자의제강간으로 처벌됩니다."),("나이를 몰랐다고 하면 되나요?","대화 기록, 프로필, 만남 장소 등 객관적 사정으로 판단합니다. 나이를 짐작할 말이 기록에 남아 있으면 받아들여지기 어렵습니다.")]),
"phishing-courier":("형사",[("보이스피싱인 줄 몰랐으면 처벌받지 않나요?","정말 몰랐다면 사기죄가 아니지만, 범죄일 수 있다고 생각하면서 한 정도(미필적 고의)만 있어도 유죄가 됩니다. 보수, 지시 방식 등 객관적 사정으로 판단합니다."),("수거책도 사기죄로 처벌되나요?","사기죄의 공범이나 방조범이 될 수 있습니다. 2026년 9월 13일 이후 행위는 20년 이하 징역 또는 5천만 원 이하 벌금입니다."),("대화방을 나가도 되나요?","나가거나 메시지를 지우지 마세요. 몰랐다는 것을 보여줄 자료도 그 대화 안에 있고, 삭제는 증거인멸로 의심받을 수 있습니다.")]),
"drunk-driving":("음주운전",[("음주운전 초범은 어떻게 처벌되나요?","혈중알코올농도 0.03% 이상 0.08% 미만은 1년 이하 징역 또는 500만 원 이하 벌금, 0.08% 이상 0.2% 미만은 1~2년 징역 또는 500만~1천만 원 벌금, 0.2% 이상은 2~5년 징역 또는 1천만~2천만 원 벌금입니다."),("측정을 거부하면 유리한가요?","아닙니다. 측정 거부는 1년 이상 5년 이하 징역 또는 500만~2천만 원 벌금으로 무겁게 처벌되고, 운전 후 술을 더 마시는 '술타기'도 같은 형으로 처벌됩니다."),("면허 취소는 언제까지 다퉈야 하나요?","이의신청은 처분을 안 날부터 60일, 행정심판은 90일 안에 해야 합니다.")]),
"school-violence":("학교폭력",[("학교폭력 기록은 생활기록부에 얼마나 남나요?","1~3호는 이행하면 기재가 유보되고, 4·5호는 졸업 후 2년, 6·7호는 졸업 후 4년, 8호는 졸업 후 4년, 9호는 영구 보존됩니다(2024년 3월 이후 기준)."),("학교장 자체해결은 언제 가능한가요?","2주 이상 진단서가 없고, 재산 피해가 복구됐고, 지속적이지 않고, 보복이 아니며, 피해학생 측이 심의를 원하지 않을 때 가능합니다."),("학폭위 결과에 불복할 수 있나요?","처분이 있음을 안 날부터 90일 안에 행정심판이나 행정소송을 제기할 수 있고, 집행정지도 함께 검토합니다.")]),
"indecent-assault":("성범죄",[("강제추행은 어떻게 처벌되나요?","형법 제298조에 따라 10년 이하 징역 또는 1천500만 원 이하 벌금입니다."),("지하철 추행은 다른 죄인가요?","사람이 밀집한 곳에서의 추행은 공중밀집장소추행(성폭력처벌법 제11조)으로 3년 이하 징역 또는 3천만 원 이하 벌금입니다."),("벌금형이면 신상정보 등록이 안 되나요?","강제추행과 공중밀집장소추행은 벌금형이 선고되어도 원칙적으로 신상정보 등록 대상이 됩니다.")]),
"rape-accusation":("성범죄",[("강간죄는 벌금형이 있나요?","없습니다. 강간과 준강간은 3년 이상의 유기징역입니다."),("술에 취한 상대와의 관계는 모두 준강간인가요?","판례는 단순히 판단력이 흐려진 정도로는 부족하고 심신상실이나 항거불능 상태여야 한다고 봅니다. 당시 취한 정도가 핵심 쟁점입니다."),("고소가 취소되면 수사가 끝나나요?","성범죄는 친고죄가 아니어서 고소가 취소되어도 수사는 계속될 수 있습니다.")]),
"assault-injury":("형사",[("폭행은 합의하면 끝나나요?","폭행죄는 반의사불벌죄여서 피해자가 처벌을 원하지 않으면 처벌할 수 없습니다. 상해는 합의해도 처벌될 수 있습니다."),("휴대폰으로 때려도 특수폭행인가요?","판례상 일상적인 물건도 사용 방법에 따라 위험한 물건이 될 수 있습니다."),("쌍방폭행이면 정당방위가 되나요?","서로 공격할 의사로 싸운 경우에는 정당방위가 쉽게 인정되지 않습니다.")]),
"fraud":("형사",[("돈을 못 갚으면 사기죄인가요?","돈을 받을 당시 갚을 의사나 능력이 없으면서 속였을 때 사기죄가 됩니다. 나중에 사정이 나빠져 못 갚은 것은 원칙적으로 민사 문제입니다."),("사기죄 처벌이 무거워졌나요?","2026년 9월 13일 이후 행위는 20년 이하 징역 또는 5천만 원 이하 벌금으로 상향됐습니다. 그 전 행위는 10년 이하 징역 또는 2천만 원 이하 벌금입니다."),("금액이 크면 어떻게 되나요?","이득액 5억 원 이상이면 특경법이 적용되어 3년 이상 유기징역, 50억 원 이상이면 무기 또는 5년 이상 징역입니다.")]),
"embezzlement":("형사",[("업무상횡령은 어떻게 처벌되나요?","형법 제356조에 따라 10년 이하 징역 또는 3천만 원 이하 벌금입니다."),("1인 회사 대표도 횡령이 되나요?","회사 돈은 대표 개인의 돈이 아니므로 1인 회사라도 횡령이 될 수 있습니다."),("돈을 갚으면 처벌받지 않나요?","합의해도 처벌 자체를 막을 수는 없지만, 피해 회복은 양형에서 가장 중요한 사정 중 하나입니다.")]),
"theft":("형사",[("절도죄는 어떻게 처벌되나요?","형법 제329조에 따라 6년 이하 징역 또는 1천만 원 이하 벌금입니다."),("길에서 주운 물건을 가져가면요?","점유이탈물횡령죄로 1년 이하 징역, 300만 원 이하 벌금 또는 과료입니다. 가게처럼 관리자가 있는 곳의 물건은 절도가 될 수 있습니다."),("무인점포 절도도 합의가 중요한가요?","피해 회복과 합의는 처분에 큰 영향을 줍니다. 초범이고 피해가 작으면 선처를 기대할 수 있는 사건이 많습니다.")]),
"drugs":("마약",[("대마 흡연은 어떻게 처벌되나요?","마약류관리법에 따라 5년 이하 징역 또는 5천만 원 이하 벌금입니다."),("모발 검사로 언제 투약까지 알 수 있나요?","머리카락 길이에 따라 몇 달 전의 투약까지 확인될 수 있습니다."),("나눠준 것도 처벌되나요?","돈을 받지 않고 나눠준 것도 수수·제공으로 평가될 수 있고, 투약보다 훨씬 무겁게 처벌됩니다.")]),
"stalking":("형사",[("스토킹은 합의하면 처벌받지 않나요?","2023년 법 개정으로 반의사불벌죄 조항이 삭제되어, 합의해도 처벌될 수 있습니다."),("스토킹은 어떻게 처벌되나요?","스토킹처벌법 제18조에 따라 3년 이하 징역 또는 3천만 원 이하 벌금, 흉기를 휴대·이용하면 5년 이하 징역 또는 5천만 원 이하 벌금입니다."),("받지 않은 전화도 스토킹인가요?","객관적으로 불안감을 일으키기에 충분하다면 받지 않은 전화도 스토킹행위가 될 수 있습니다.")]),
"false-accusation":("형사",[("무혐의를 받으면 상대는 무고죄인가요?","아닙니다. 신고 내용이 허위이고 신고자가 허위임을 알았어야 합니다. 증거 부족으로 무혐의가 된 것만으로는 부족합니다."),("무고죄는 어떻게 처벌되나요?","형법 제156조에 따라 10년 이하 징역 또는 1천500만 원 이하 벌금입니다."),("맞고소는 언제 하는 게 좋나요?","원래 사건에서 허위임을 보여줄 자료를 충분히 확보한 뒤 시점을 정하는 것이 일반적입니다.")]),
"eviction":("부동산",[("월세가 몇 달 밀리면 계약을 해지할 수 있나요?","주택은 연체액이 2기분, 상가는 3기분에 이르면 해지할 수 있습니다."),("세입자가 없는 사이 짐을 빼도 되나요?","안 됩니다. 주거침입, 재물손괴 등으로 임대인이 처벌받을 수 있습니다."),("명도소송 전에 해야 할 것이 있나요?","소송 중 점유가 넘어가는 것을 막기 위해 점유이전금지가처분을 먼저 신청하는 것이 일반적입니다.")]),
"loan-recovery":("민사",[("차용증이 없어도 받을 수 있나요?","송금 내역과 함께 빌려 달라는 메시지, 녹음, 일부 변제 기록이 있으면 대여 사실을 입증할 수 있습니다."),("빌려준 돈은 언제까지 청구할 수 있나요?","개인 간 대여금은 10년, 사업상 거래에서 생긴 상사채권은 5년의 소멸시효가 적용됩니다."),("내용증명을 보내면 시효가 멈추나요?","확정적으로 멈추지 않습니다. 6개월 안에 소송, 지급명령, 가압류 같은 후속 조치를 해야 효력이 유지됩니다.")]),
"divorce-property":("이혼",[("재산분할은 언제까지 청구해야 하나요?","이혼한 날부터 2년이 지나면 재산분할청구권이 소멸합니다."),("협의이혼은 바로 되나요?","숙려기간이 있어 미성년 자녀가 있으면 3개월, 없으면 1개월이 원칙입니다."),("이혼 직전에 상대가 재산을 넘기면요?","그 처분을 취소하고 원상회복을 청구할 수 있습니다. 취소 원인을 안 날부터 1년, 처분일부터 5년 안에 해야 합니다.")]),
"inheritance-renounce":("상속",[("상속포기는 언제까지 해야 하나요?","상속개시가 있음을 안 날부터 3개월 안에 가정법원에 신고해야 합니다."),("자녀가 모두 포기하면 끝나나요?","상속권이 다음 순위로 넘어가 친척에게 빚 독촉이 갈 수 있어, 한 사람이 한정승인을 하고 나머지는 포기하는 방법을 많이 씁니다."),("3개월이 지났으면 방법이 없나요?","빚이 더 많다는 사실을 중대한 과실 없이 몰랐다면, 안 날부터 3개월 안에 특별한정승인을 할 수 있습니다.")]),
"forced-heirship":("상속",[("형제자매도 유류분을 청구할 수 있나요?","2024년 4월 헌법재판소 위헌 결정으로 형제자매의 유류분은 효력을 잃어 청구할 수 없습니다."),("유류분은 얼마인가요?","자녀와 배우자는 법정상속분의 2분의 1, 부모는 3분의 1입니다."),("유류분 청구 기한은요?","상속개시와 반환할 증여·유증을 안 날부터 1년, 상속개시부터 10년 중 먼저 오는 때에 소멸합니다.")]),
"unfair-dismissal":("노동",[("부당해고 구제신청은 언제까지 하나요?","해고된 날부터 3개월 안에 노동위원회에 신청해야 합니다. 상시 5명 이상 사업장이 대상입니다."),("문자로 해고 통보를 받았는데 유효한가요?","해고는 사유와 시기를 서면으로 알려야 효력이 생기므로, 말이나 단순 통보만으로 한 해고는 다툴 수 있습니다."),("해고예고수당은 언제 받나요?","30일 전에 예고하지 않았다면 30일분 이상의 통상임금을 받을 수 있습니다. 계속 근로 3개월 미만이면 예외입니다.")]),
"unpaid-wages":("노동",[("퇴직금은 언제까지 받아야 하나요?","퇴직한 날부터 14일 안에 지급해야 하고, 늦으면 연 20%의 지연이자가 붙습니다."),("임금체불은 처벌되나요?","3년 이하 징역 또는 3천만 원 이하 벌금이며, 근로자가 처벌을 원하지 않으면 처벌할 수 없는 반의사불벌죄입니다."),("못 받은 임금은 언제까지 청구할 수 있나요?","임금과 퇴직금 채권은 3년간 행사하지 않으면 소멸합니다.")]),
"workplace-bullying":("노동",[("5인 미만 회사도 직장 내 괴롭힘이 적용되나요?","근로기준법의 직장 내 괴롭힘 조항은 5명 미만 사업장에는 적용되지 않지만, 형사 고소나 손해배상은 가능합니다."),("신고했다고 불이익을 주면요?","신고자·피해자에 대한 해고 등 불리한 처우는 3년 이하 징역 또는 3천만 원 이하 벌금으로 처벌됩니다."),("녹음해도 되나요?","본인이 대화에 참여한 상태의 녹음은 일반적으로 허용되지만, 다른 사람들끼리의 대화를 몰래 녹음하면 불법이 될 수 있습니다.")]),
"business-suspension":("행정",[("영업정지는 언제까지 다퉈야 하나요?","행정심판은 처분을 안 날부터 90일, 있은 날부터 180일 안에 청구해야 합니다."),("행정심판을 내면 영업정지가 멈추나요?","자동으로 멈추지 않으므로 집행정지를 함께 신청하는 것이 일반적입니다."),("무엇을 주장할 수 있나요?","위반 사실, 절차상 하자, 처분이 지나치게 무거운지(재량권 일탈·남용) 등을 주장합니다.")]),
"public-servant-discipline":("행정",[("징계에 불복하려면 언제까지 하나요?","처분사유설명서를 받은 날부터 30일 안에 소청심사를 청구해야 합니다."),("소청했다가 징계가 더 무거워지나요?","소청심사위원회는 원래 징계보다 무거운 결정을 할 수 없습니다."),("바로 행정소송을 낼 수 있나요?","공무원 징계는 원칙적으로 소청심사를 먼저 거쳐야 행정소송을 낼 수 있습니다.")]),
"deepfake":("성범죄",[("딥페이크를 만들기만 해도 처벌되나요?", "네. 2024년 10월 개정으로 반포 목적 요건이 삭제되어, 편집·합성만 해도 7년 이하 징역 또는 5천만 원 이하 벌금으로 처벌됩니다."), ("딥페이크 영상을 보기만 해도 처벌되나요?", "2024년 10월 16일부터 허위영상물을 소지·구입·저장·시청한 사람도 3년 이하 징역 또는 3천만 원 이하 벌금으로 처벌됩니다."), ("딥페이크도 신상정보 등록 대상인가요?", "제14조의2와 제14조의3은 등록 대상 범죄이며, 벌금형이어도 등록에서 빠지는 예외가 없습니다.")]),
"filming-threat":("성범죄",[("동의하고 찍은 영상도 유포하면 처벌되나요?", "네. 촬영 당시 동의했더라도 나중에 의사에 반하여 반포하면 7년 이하 징역 또는 5천만 원 이하 벌금으로 처벌됩니다."), ("유포하겠다고 말만 해도 처벌되나요?", "촬영물을 이용한 협박은 1년 이상의 유기징역, 그 협박으로 무언가를 하게 했다면 3년 이상의 유기징역이며 벌금형이 없습니다."), ("합의하면 협박 사건이 끝나나요?", "촬영물 이용 협박죄에는 반의사불벌 규정이 없어 합의해도 사건이 자동으로 끝나지 않습니다.")]),
"csam-possession":("성범죄",[("성착취물을 소지만 해도 처벌되나요?", "아동·청소년성착취물임을 알면서 소지·시청하면 1년 이상의 징역으로, 벌금형이 없습니다."), ("파일공유 프로그램으로 받기만 했는데 배포인가요?", "내려받는 동안 자동으로 업로드되는 구조라면 배포가 문제될 수 있고, 배포는 3년 이상의 징역입니다."), ("미성년자인 줄 몰랐다면요?", "파일 제목, 썸네일, 설정, 받은 경로 등 객관적 정황으로 인식 여부를 판단합니다.")]),
"online-grooming":("성범죄",[("온라인 그루밍은 어떻게 처벌되나요?", "아청법 제15조의2에 따라 3년 이하 징역 또는 3천만 원 이하 벌금입니다."), ("한 번 성적인 메시지를 보낸 것도 그루밍인가요?", "제1호는 지속적 또는 반복적인 대화를 요건으로 해서, 한두 번의 메시지만으로는 바로 적용되기 어렵습니다. 통매음이 문제될 수는 있습니다."), ("상대가 16세 미만이면 달라지나요?", "16세 미만에게는 성적 착취 목적이라는 요건 없이 같은 형으로 처벌됩니다.")]),
"workplace-power-assault":("성범죄",[("업무상 위력 추행은 어떻게 처벌되나요?", "성폭력처벌법 제10조에 따라 3년 이하 징역 또는 1천500만 원 이하 벌금입니다."), ("폭행이나 협박이 없었는데도 성립하나요?", "위력에는 지위나 권세를 이용하는 것도 포함되고, 피해자의 의사가 현실적으로 제압될 필요까지는 없다는 것이 판례입니다."), ("직속 부하가 아니어도 해당하나요?", "직장 안에서 사실상 보호·감독을 받는 상황에 있는 사람도 포함된다는 것이 대법원의 태도입니다.")]),
"harassment-vs-assault":("성범죄",[("직장 내 성희롱도 형사처벌되나요?", "성희롱 자체는 원칙적으로 회사 징계 대상입니다. 다만 신체 접촉, 성적 메시지 전송, 몰래 촬영 등은 강제추행·통매음·불법촬영 등으로 형사처벌될 수 있습니다."), ("회사가 조사를 안 하면 어떻게 되나요?", "사업주가 조사를 하지 않거나 필요한 조치를 하지 않으면 500만 원 이하 과태료 대상입니다."), ("신고했다가 불이익을 받으면요?", "신고자나 피해 근로자에 대한 불리한 처우는 3년 이하 징역 또는 3천만 원 이하 벌금으로 처벌됩니다.")]),
"public-indecency":("성범죄",[("공연음란죄는 어떻게 처벌되나요?", "형법 제245조에 따라 1년 이하 징역, 500만 원 이하 벌금, 구류 또는 과료입니다."), ("공연음란도 신상정보 등록이 되나요?", "공연음란죄만으로 처벌되는 경우에는 신상정보 등록 대상이 아닙니다."), ("벌금형이어도 취업제한이 붙나요?", "공연음란은 성폭력범죄에 포함되어 벌금형이라도 취업제한명령이 함께 선고될 수 있습니다.")]),
"restroom-intrusion":("성범죄",[("이성 화장실에 실수로 들어가도 처벌되나요?", "성적 욕망을 만족시킬 목적이 있어야 성립하므로, 착오 출입이라면 범죄가 되지 않을 수 있습니다. 실제로 무죄가 선고된 사례도 있습니다."), ("화장실 침입은 어떻게 처벌되나요?", "성폭력처벌법 제12조에 따라 1년 이하 징역 또는 1천만 원 이하 벌금입니다."), ("벌금형이면 신상정보 등록이 되나요?", "이 죄로 벌금형을 선고받으면 신상정보 등록 대상에서 제외됩니다.")]),
"prostitution":("성범죄",[("성매매는 어떻게 처벌되나요?", "성매매처벌법 제21조에 따라 1년 이하 징역이나 300만 원 이하 벌금·구류 또는 과료입니다."), ("초범이면 무조건 존스쿨인가요?", "아닙니다. 존스쿨은 검사가 대상이라고 판단해야 주어지는 교육조건부 기소유예로, 방문이 반복된 정황이 있으면 벌금형으로 처리될 수 있습니다."), ("존스쿨을 받으면 전과가 남나요?", "기소유예는 전과(범죄경력자료)로 남지 않지만, 수사경력자료는 성인의 경우 5년간 보존됩니다.")]),
"sex-offender-registry":("성범죄",[("벌금형이면 신상정보 등록이 안 되나요?", "통매음과 성적목적다중이용장소침입은 벌금형이면 제외되지만, 강제추행 등 다른 성범죄는 벌금형이어도 등록됩니다."), ("신상정보 등록은 몇 년인가요?", "선고형에 따라 벌금형 10년, 3년 이하 징역 15년, 3년 초과 10년 이하 징역 20년, 그 이상은 30년입니다."), ("등록되면 언제까지 신고해야 하나요?", "판결이 확정된 날부터 30일 안에 관할 경찰관서에 신상정보를 제출하고, 바뀌면 20일 안에 변경 신고를 해야 합니다.")]),
"employment-restriction":("성범죄",[("벌금형이어도 취업제한명령이 나오나요?", "네. 성범죄로 형을 선고하면 약식명령을 포함해 원칙적으로 취업제한명령을 함께 선고하도록 되어 있습니다."), ("취업제한은 몇 년인가요?", "법원이 사건마다 10년을 넘지 않는 범위에서 기간을 정합니다."), ("취업제한을 면제받을 수 있나요?", "재범 위험성이 현저히 낮거나 취업을 제한해서는 안 되는 특별한 사정이 있으면 선고하지 않을 수 있어, 이를 뒷받침할 자료를 내야 합니다.")]),
"public-servant-sex-crime":("성범죄",[("공무원이 성범죄로 벌금형을 받으면 퇴직하나요?", "성폭력범죄로 100만 원 이상 벌금형이 확정되면 결격사유가 되어 당연퇴직합니다."), ("선고유예를 받으면 괜찮나요?", "성폭력범죄로 선고유예를 받은 경우에도 당연퇴직 사유가 되도록 정해져 있습니다."), ("교사는 기준이 다른가요?", "교육공무원법은 성폭력범죄로 100만 원 이상 벌금형 이상이 확정된 사람을 기간 제한 없이 교원 결격사유로 정하고 있습니다.")]),
"sex-crime-settlement":("성범죄",[("성범죄는 합의하면 끝나나요?", "친고죄가 아니어서 합의해도 자동으로 끝나지 않지만, 합의는 처분과 양형에서 가장 중요한 사정입니다."), ("피해자 연락처를 모르면 공탁할 수 있나요?", "형사공탁 특례에 따라 피해자 인적사항을 몰라도 법원과 사건번호 등을 적어 공탁할 수 있습니다."), ("형사공탁은 무엇이 달라졌나요?", "2025년 1월 17일부터 법원은 선고 전에 피해자 의견을 들어야 하고, 공탁금 회수도 원칙적으로 제한됩니다.")]),
"sex-crime-first-offense":("성범죄",[("성범죄 초범이면 기소유예를 받을 수 있나요?", "가능한 사건도 있지만 죄명, 합의, 행위의 정도, 재범 방지 노력 등에 따라 결과가 갈립니다."), ("벌금형이 없는 성범죄는 무엇인가요?", "강간·준강간, 촬영물 이용 협박·강요, 아동·청소년성착취물 소지·시청 등은 벌금형이 없습니다."), ("기소유예도 신상정보 등록이 되나요?", "기소유예는 유죄판결이 아니어서 신상정보 등록 대상이 아닙니다.")]),
"sex-crime-victim":("성범죄",[("성범죄 고소는 언제까지 해야 하나요?", "성범죄는 친고죄가 아니어서 고소기간 제한은 없고, 공소시효 안에서 고소할 수 있습니다. 미성년 피해 등에는 공소시효 특례가 있습니다."), ("변호사 비용이 부담되면요?", "성범죄 피해자는 변호사가 없으면 검사가 선정하는 국선변호사의 도움을 받을 수 있습니다."), ("조사에 가족이 함께 들어갈 수 있나요?", "신뢰관계에 있는 사람의 동석을 요청할 수 있습니다.")]),
"consensual-divorce":("이혼",[('협의이혼 숙려기간은 얼마인가요?', '미성년 자녀(임신 중 포함)가 있으면 3개월, 없으면 1개월입니다.'), ('법원 확인을 받으면 바로 이혼되나요?', '확인서 등본을 받은 날부터 3개월 안에 이혼신고를 해야 효력이 생기고, 그 기간이 지나면 확인이 효력을 잃습니다.'), ('협의이혼 때 재산분할도 정하나요?', '협의이혼 서류에는 재산분할 칸이 없어 별도 합의서를 써야 하고, 합의하지 않았다면 이혼한 날부터 2년 안에 청구해야 합니다.')]),
"divorce-grounds":("이혼",[('재판상 이혼사유는 무엇인가요?', '민법 제840조의 부정행위, 악의의 유기, 심히 부당한 대우(2가지), 3년 이상 생사불명, 혼인을 계속하기 어려운 중대한 사유입니다.'), ('외도를 알게 된 지 오래됐는데 이혼할 수 있나요?', '부정행위는 안 날부터 6개월, 있은 날부터 2년이 지나거나 용서한 경우 그 사유로는 청구할 수 없습니다. 다른 사유로 구성할 수 있는지 검토가 필요합니다.'), ('잘못한 쪽도 이혼을 청구할 수 있나요?', '원칙적으로 허용되지 않지만, 상대도 혼인계속의사가 없으면서 보복 감정으로 거부하는 경우 등에는 예외적으로 허용됩니다.')]),
"adultery-lawsuit":("이혼",[('상간녀 소송은 언제까지 해야 하나요?', '손해와 가해자를 안 날부터 3년, 불법행위가 있은 날부터 10년 안에 청구해야 합니다. 부정행위로 이혼에 이르렀다면 이혼 원인 위자료의 시효는 혼인 해소 시부터 진행한다는 대법원 판결이 있습니다.'), ('이미 별거 중일 때 만난 상대에게도 청구할 수 있나요?', '혼인이 실질적으로 파탄된 뒤의 관계는 원칙적으로 불법행위가 아니라는 것이 판례입니다. 다만 파탄 사실은 상간자 쪽이 증명해야 합니다.'), ('배우자가 위자료를 다 주면 상간자에게 또 받을 수 있나요?', '두 사람의 책임은 연대 관계여서 배우자가 지급한 범위에서 상간자의 채무도 소멸합니다.')]),
"property-division":("이혼",[('결혼 전 재산도 나누나요?', '혼인 전 재산이나 상속·증여받은 재산은 원칙적으로 제외되지만, 상대방이 그 재산의 유지·증가에 기여했다면 대상이 될 수 있습니다.'), ('아직 퇴직하지 않았는데 퇴직금도 나누나요?', '재직 중이어도 일정 시점에 퇴직한다고 가정한 예상 퇴직급여를 분할 대상에 포함할 수 있습니다.'), ('재산분할은 언제까지 청구하나요?', '이혼한 날부터 2년이 지나면 청구권이 소멸합니다.')]),
"common-law-property":("이혼",[('동거만 해도 재산분할을 받을 수 있나요?', '혼인 의사와 부부로서의 공동생활이 인정되는 사실혼이어야 하며, 단순 동거와는 다릅니다.'), ('사실혼 재산분할은 언제까지 청구하나요?', '사실혼이 해소된 때부터 2년 안에 청구해야 합니다.'), ('사실혼 배우자도 상속받을 수 있나요?', '사실혼 배우자에게는 상속권이 없습니다.')]),
"divorce-alimony":("이혼",[('위자료와 재산분할은 어떻게 다른가요?', '위자료는 혼인 파탄 책임에 대한 손해배상이고, 재산분할은 함께 만든 재산의 정산이어서 유책 여부와 관계없이 청구할 수 있습니다.'), ('이혼 위자료는 얼마인가요?', '정해진 금액표는 없고, 유책 행위의 정도, 혼인 기간, 자녀, 쌍방 책임 비율 등을 종합해 법원이 정합니다.'), ('위자료는 언제까지 청구하나요?', '손해배상청구권이어서 3년의 소멸시효가 적용됩니다.')]),
"divorce-lawsuit-process":("이혼",[('이혼소송은 바로 재판으로 가나요?', '이혼소송은 조정을 먼저 거치는 것이 원칙이어서 법원이 사건을 조정에 회부할 수 있습니다.'), ('상대가 답변서를 안 내면 이기나요?', '이혼사건은 법원이 직권으로 사실을 조사하므로 답변서를 내지 않았다는 이유만으로 그대로 판결되지는 않습니다.'), ('소송 중 아이는 누가 키우나요?', '사전처분으로 판결 전까지 임시 양육자와 양육비를 정해 달라고 신청할 수 있습니다.')]),
"late-life-divorce":("이혼",[('이혼하면 배우자 국민연금을 나눠 받을 수 있나요?', '배우자의 가입기간 중 혼인 기간이 5년 이상이고, 이혼, 전 배우자의 노령연금 수급권, 본인의 지급 개시 연령 요건을 모두 갖추면 분할연금을 받을 수 있습니다.'), ('분할연금은 언제까지 청구하나요?', '요건을 모두 갖춘 날부터 5년 안에 국민연금공단에 청구해야 합니다.'), ('공무원연금도 나눌 수 있나요?', '공무원연금에도 분할연금 제도가 있어, 재직기간 중 혼인 기간이 5년 이상이고 일정 요건을 갖추면 청구할 수 있습니다.')]),
"custody-criteria":("이혼",[('양육권은 어떤 기준으로 정하나요?', '자녀의 복리가 기준이며, 지금까지의 주 양육자, 애착 관계, 양육 환경, 자녀의 나이와 의사 등을 종합합니다.'), ('아이 의견도 듣나요?', '자녀가 13세 이상이면 법원은 원칙적으로 자녀의 의견을 들어야 합니다.'), ('돈을 더 많이 버는 쪽이 유리한가요?', '경제 사정은 양육비로 보완할 수 있어 결정적인 기준은 아닙니다.')]),
"child-support-unpaid":("이혼",[('양육비를 안 주면 감치되나요?', '이행명령을 받고도 정당한 이유 없이 3기 이상 지급하지 않으면 30일 범위에서 감치를 명할 수 있습니다.'), ('양육비 미지급도 형사처벌되나요?', '감치명령을 받고도 1년 안에 정당한 사유 없이 지급하지 않으면 1년 이하 징역 또는 1천만 원 이하 벌금으로 처벌될 수 있습니다.'), ('양육비 선지급제는 누가 받을 수 있나요?', '양육비를 일정 기간 연속해 받지 못한 경우 자녀 1인당 월 20만 원까지 국가가 먼저 지급하며, 2026년 10월 29일부터 소득 요건이 폐지됐습니다.')]),
"child-support-increase":("이혼",[('정한 양육비를 올릴 수 있나요?', '자녀 진학, 물가 상승, 상대 소득 증가 등 사정변경이 있으면 자녀의 복리를 기준으로 증액을 청구할 수 있습니다.'), ('과거 양육비도 받을 수 있나요?', '양육비를 정하지 않고 혼자 키웠다면 지나간 기간의 양육비도 분담을 청구할 수 있습니다.'), ('과거 양육비 청구 기한은요?', '2024년 대법원 전원합의체 결정에 따라 자녀가 성년이 된 때부터 소멸시효가 진행해, 성년 후 10년이 지나면 청구하기 어렵습니다.')]),
"visitation-rights":("이혼",[('양육비를 안 주면 아이를 안 보여줘도 되나요?', '안 됩니다. 양육비와 면접교섭은 별개의 의무여서 각각 따로 강제할 수 있습니다.'), ('조부모도 손주를 만날 수 있나요?', '비양육 부모가 사망하거나 질병·외국 거주 등으로 면접교섭을 할 수 없으면 그 부모의 직계존속이 가정법원에 청구할 수 있습니다.'), ('면접교섭을 계속 방해하면요?', '이행명령을 신청할 수 있고, 이를 어기면 1천만 원 이하 과태료가 부과될 수 있으며, 반복되면 양육자 변경 사유가 될 수 있습니다.')]),
"custody-change":("이혼",[('이혼 후 양육권을 바꿀 수 있나요?', '자녀의 복리를 위해 필요하면 가정법원에 양육자 변경(민법 제837조)이나 친권자 변경(제909조)을 청구할 수 있습니다.'), ('어떤 경우에 변경되나요?', '양육 환경 악화, 방임·학대, 지속적인 면접교섭 방해, 자녀의 의사 등 처음 정한 뒤 달라진 사정이 있어야 합니다.'), ('심판 전에 급하게 아이를 데려와야 하면요?', '긴급한 사정이 있으면 임시로 양육자를 정하는 사전처분을 신청할 수 있습니다.')]),
"divorce-mediation":("이혼",[('조정이혼은 효력이 있나요?', '조정이 성립하면 재판상 화해와 같은 효력, 즉 확정판결과 같은 효력이 생깁니다.'), ('조정을 갈음하는 결정에 불복하려면?', '결정을 송달받은 날부터 2주 안에 이의신청을 해야 하고, 그러면 소송 절차로 넘어갑니다.'), ('조정 후 마음이 바뀌면 되돌릴 수 있나요?', '조정조서는 당연무효이거나 준재심으로 취소되지 않는 한 무효를 주장하기 매우 어렵습니다.')]),
"cooling-off-shorten":("이혼",[('숙려기간을 줄일 수 있나요?', '폭력 등으로 참을 수 없는 고통이 예상되는 등 이혼해야 할 급박한 사정이 있으면 법원이 단축하거나 면제할 수 있습니다.'), ('어떤 자료가 필요한가요?', '진단서, 112 신고 내역, 상담 기록, 문자·녹음 등 급박한 사정을 보여주는 자료가 필요합니다.'), ('둘 다 이혼에 동의하면 줄여 주나요?', '이혼 의사가 확고하다는 것만으로는 단축 사유로 받아들여지기 어렵습니다.')]),
"separation-divorce":("이혼",[('별거만으로 이혼할 수 있나요?', '별거 자체는 이혼사유가 아니지만, 장기 별거로 혼인이 회복할 수 없을 정도로 파탄됐다면 제6호 사유가 될 수 있습니다.'), ('집을 나간 쪽이 불리한가요?', '정당한 이유 없이 나가 연락과 생활비를 끊었다면 악의의 유기로 평가될 수 있지만, 폭력을 피해 나온 경우는 다릅니다.'), ('별거 중 생활비를 받을 수 있나요?', '부부는 공동생활 비용을 함께 부담할 의무가 있어 별거 중에도 생활비 분담을 청구할 수 있습니다.')]),
"marriage-annulment":("이혼",[('속아서 결혼했으면 무효인가요?', '사기에 의한 혼인은 원칙적으로 무효가 아니라 취소 사유이며, 사기를 안 날부터 3개월 안에 청구해야 합니다.'), ('이혼한 뒤에도 혼인무효를 구할 수 있나요?', '2024년 대법원 전원합의체 판결로 이혼 후에도 혼인무효 확인을 구할 수 있게 됐습니다.'), ('혼인취소와 이혼은 무엇이 다른가요?', '혼인무효는 처음부터 혼인이 없었던 것으로 보지만, 혼인취소와 이혼은 과거로 소급하지 않습니다.')]),
"broken-engagement":("이혼",[('파혼당하면 위자료를 받을 수 있나요?', '정당한 이유 없이 약혼을 깬 과실 있는 상대방에게 재산상 손해와 위자료를 청구할 수 있습니다(민법 제806조).'), ('부모가 반대해서 파혼하는 것도 정당한가요?', '단순한 마음의 변화나 부모 반대는 일반적으로 정당한 해제 사유가 되기 어렵습니다.'), ('예물은 돌려받을 수 있나요?', '혼인이 무산되면 원칙적으로 반환하지만, 파혼에 책임이 있는 쪽은 자기가 준 예물의 반환을 청구하기 어렵습니다.')]),
"post-divorce-property":("이혼",[('협의이혼 후 재산분할을 청구할 수 있나요?', '따로 합의하지 않았다면 이혼한 날부터 2년 안에 가정법원에 청구할 수 있습니다.'), ('내용증명을 보내면 기한이 지켜지나요?', '재산분할 청구 기한은 법원에 청구해야 지켜지며, 내용증명만으로는 부족합니다.'), ('이혼 전에 재산을 빼돌렸다면요?', '그 처분을 취소하고 원상회복을 청구할 수 있으며, 안 날부터 1년, 처분일부터 5년 안에 해야 합니다.')]),
"divorce-appeal":("이혼",[('이혼 판결 항소기간은요?', '판결정본이 송달된 날부터 14일 안에 항소해야 합니다.'), ('재산분할만 다툴 수 있나요?', '불복 범위를 정해 일부만 다툴 수 있지만, 상대방도 항소하면 다른 부분이 다시 심리될 수 있습니다.'), ('항소 이유가 있어도 기각될 수 있나요?', '가사소송법은 판결 변경이 형평이나 가정의 평화에 맞지 않으면 항소를 기각할 수 있게 정하고 있습니다.')]),
"jealousy-personality-divorce":("이혼",[('성격 차이로 이혼소송이 되나요?', '성격 차이만으로는 어렵고, 그로 인해 혼인이 회복할 수 없을 정도로 파탄됐다는 구체적 사정을 보여줘야 합니다.'), ('의부증도 이혼사유인가요?', '근거 없는 의심과 감시·통제로 정상적인 생활이 어려워졌다면 제6호 사유가, 폭언·폭행으로 이어졌다면 제3호 사유도 될 수 있습니다.'), ('상대가 정신질환이면요?', '법원은 증세의 정도와 치료로 회복될 가능성을 함께 보므로 치료 경과와 회복 노력 자료가 중요합니다.')]),
"common-law-dissolution":("이혼",[('사실혼을 끝내려면 법원에 가야 하나요?', '사실혼은 합의나 한쪽의 일방적 의사로 해소되며 법원 절차는 필요하지 않습니다.'), ('사실혼 중 낳은 아이의 양육비는요?', '아버지와의 법적 관계는 인지가 있어야 생기며, 인지가 되면 양육비를 청구할 수 있습니다.'), ('사실혼 배우자가 사망하면요?', '상속권은 없지만 주택 임차권 승계, 상속인이 없을 때의 특별연고자 분여 등 보호 장치가 있습니다.')]),
"dui-first-fine":("음주운전",[('음주운전 초범 벌금은 얼마인가요?', '정해진 금액표는 없고, 0.03~0.08%는 500만 원 이하, 0.08~0.2%는 500만~1천만 원, 0.2% 이상은 1천만~2천만 원 범위에서 수치·경위·반성 자료 등을 고려해 정해집니다.'), ('약식명령에 불복할 수 있나요?', '약식명령을 받은 날부터 7일 안에 정식재판을 청구할 수 있습니다.'), ('몇 년 전 전력도 재범인가요?', '벌금 이상의 형이 확정된 날부터 10년 안에 다시 위반해야 가중 규정이 적용됩니다.')]),
"dui-repeat":("음주운전",[('음주운전 2회면 어떻게 처벌되나요?', '10년 안의 재범이면 0.03~0.2%는 1년 이상 5년 이하 징역 또는 500만~2천만 원 벌금, 0.2% 이상은 2년 이상 6년 이하 징역 또는 1천만~3천만 원 벌금입니다.'), ('2회 적발되면 면허는 언제 다시 따나요?', '음주운전 2회 이상이면 결격기간이 2년, 사고까지 있으면 3년입니다.'), ('음주운전 방지장치는 누가 달아야 하나요?', '음주운전으로 취소된 뒤 5년 안에 다시 음주운전으로 취소된 사람은 결격기간 뒤 방지장치를 단 조건부 면허를 받아야 하며, 2026년 10월부터 적용되고 있습니다.')]),
"license-revocation-reacquire":("음주운전",[('음주운전 면허취소 결격기간은요?', '단순 음주·측정불응 1년, 2회 이상 또는 음주 사고 2년, 2회 이상이면서 사고 3년, 사망사고·사상 후 도주 5년입니다.'), ('결격기간을 줄일 수 있나요?', '결격기간 자체를 줄이는 제도는 없고, 취소 처분이 110일 정지로 감경되면 결격기간이 생기지 않습니다.'), ('다시 면허를 따려면 무엇이 필요한가요?', '결격기간이 지난 뒤 특별교통안전 의무교육을 받고 적성검사와 학과·기능·도로주행 시험을 다시 봐야 합니다.')]),
"dui-license-appeal":("음주운전",[('음주운전 면허취소 구제가 되나요?', '운전이 생계에 중요한 수단인 사람 등이 감경 제외 사유에 해당하지 않으면 취소가 110일 정지로 감경될 수 있습니다.'), ('어떤 경우 감경이 안 되나요?', '혈중알코올농도 0.1% 초과, 음주 인적피해 사고, 측정불응·도주·경찰관 폭행, 5년 내 3회 이상 인적피해 사고, 5년 내 음주운전 전력 중 하나라도 있으면 감경되지 않습니다.'), ('언제까지 신청하나요?', '이의신청은 처분을 받은 날부터 60일, 행정심판은 처분이 있음을 안 날부터 90일 안에 해야 합니다.')]),
"breath-test-refusal":("음주운전",[('음주측정을 거부하면 어떻게 되나요?', '1년 이상 5년 이하 징역 또는 500만~2천만 원 벌금이며, 면허가 취소되고 생계형 감경도 받을 수 없습니다.'), ('숨을 약하게 불어도 측정거부인가요?', '숨을 제대로 불지 않는 등의 행동이 반복되어 측정 의사가 없다는 것이 객관적으로 명백하면 측정거부가 될 수 있습니다.'), ('호흡측정 결과가 억울하면요?', '일단 측정에 응한 뒤 결과에 동의하지 않으면 혈액 채취로 다시 측정해 달라고 요구할 수 있습니다.')]),
"dui-accident":("음주운전",[('음주운전으로 사람을 다치게 하면요?', '정상적인 운전이 곤란한 상태였다면 위험운전치상으로 1년 이상 15년 이하 징역 또는 1천만~3천만 원 벌금입니다.'), ('보험에 들었고 합의하면 처벌 안 받나요?', '음주운전 사고는 12대 중과실이어서 보험·합의와 관계없이 처벌될 수 있지만, 합의는 형을 정할 때 매우 중요합니다.'), ('음주 사고 후 면허는요?', '음주운전 교통사고는 결격기간 2년, 사망사고나 사상 후 도주는 5년입니다.')]),
"dui-arrest":("음주운전",[('음주운전으로 구속되나요?', '단순 초범은 대부분 불구속이지만, 재범·고농도·사고·도주·측정거부·무면허가 겹치면 구속 가능성이 커집니다.'), ('집행유예 중 음주운전을 하면요?', '유예기간 중 고의 범죄로 금고 이상의 실형이 확정되면 집행유예가 효력을 잃어 이전 형까지 집행될 수 있습니다.'), ('구속을 피하려면 무엇을 준비하나요?', '주거·직업의 안정성, 차량 처분과 치료 등 재범 방지 조치, 피해 회복 자료를 미리 준비해야 합니다.')]),
"dui-suspended-sentence":("음주운전",[('음주운전도 기소유예가 나오나요?', '가능은 하지만 드물며, 수치가 낮고 초범이며 운전 거리가 짧은 등 예외적인 사안에서 검토됩니다.'), ('집행유예는 언제 가능한가요?', '3년 이하의 징역을 선고할 때 가능하고, 보호관찰·사회봉사·수강명령이 함께 붙을 수 있습니다.'), ('공무원이 집행유예를 받으면요?', '금고 이상 형의 집행유예가 확정되면 결격사유에 해당해 당연퇴직합니다.')]),
"dui-mitigation-materials":("음주운전",[('음주운전 반성문은 어떻게 쓰나요?', '경위를 솔직하게 쓰고 책임을 인정하며, 구체적인 재발 방지 계획을 담아야 합니다. 책임을 줄이려는 표현은 피하세요.'), ('어떤 양형자료가 효과적인가요?', '차량 매각·폐차 증빙, 알코올 진료·상담 기록, 교육 이수증 등 재범을 구조적으로 막은 객관적 자료가 설득력이 있습니다.'), ('탄원서는 누가 써야 하나요?', '가족이나 직장 동료가 재범 방지를 어떻게 돕겠다는 구체적 내용을 담아 쓰는 것이 효과적입니다.')]),
"dui-accomplice":("음주운전",[('음주운전 차에 타기만 해도 처벌되나요?', '단순 동승만으로는 처벌되지 않지만, 음주 사실을 알면서 운전을 돕거나 허용했다면 방조범이 될 수 있습니다.'), ('차 열쇠를 건네면 방조인가요?', '운전자가 취한 것을 알면서 차 열쇠를 건넸다면 방조가 문제되는 전형적인 경우입니다.'), ('방조범은 어떻게 처벌되나요?', '형법 제32조에 따라 정범의 형보다 감경하여 처벌합니다.')]),
"public-servant-dui":("음주운전",[('공무원 음주운전 첫 적발은 어떤 징계인가요?', '0.08% 미만은 정직~감봉, 0.08~0.2%는 강등~정직, 0.2% 이상이나 측정불응은 해임~정직이 기준입니다.'), ('두 번 적발되면요?', '2회 음주운전은 파면~강등, 3회 이상은 파면~해임이 기준입니다.'), ('벌금형이면 퇴직하나요?', '음주운전 벌금형만으로 당연퇴직하지는 않지만, 금고 이상 형의 집행유예가 확정되면 당연퇴직합니다.')]),
"pm-bicycle-dui":("음주운전",[('전동킥보드 음주운전 범칙금은요?', '개인형 이동장치 음주운전은 범칙금 10만 원, 측정불응은 13만 원입니다.'), ('자전거 음주운전도 처벌되나요?', '자전거 음주운전은 범칙금 3만 원, 측정불응은 10만 원입니다.'), ('킥보드 음주로 자동차 면허도 정지되나요?', '전동킥보드는 원동기장치자전거의 일종이어서 음주운전 시 운전면허 정지·취소 처분이 내려질 수 있습니다.')]),
"unlicensed-driving":("음주운전",[('무면허운전 처벌은요?', '자동차 무면허운전은 1년 이하 징역 또는 300만 원 이하 벌금입니다.'), ('면허 정지 중 운전도 무면허인가요?', '네. 면허가 정지되거나 취소된 상태에서 운전한 것도 무면허운전입니다.'), ('취소된 줄 몰랐다면요?', '유효한 면허가 없다는 것을 알아야 성립하므로 정말 몰랐다면 처벌되지 않을 수 있지만, 통지를 받았다면 알았다고 봅니다.')]),
"unlicensed-dui":("음주운전",[('무면허 음주운전은 어떻게 처벌되나요?', '한 번의 운전으로 두 죄가 성립하면 가장 무거운 죄의 형으로 처벌하며, 대부분 음주운전죄의 형이 기준이 되고 무면허는 불리한 사정이 됩니다.'), ('무면허 음주운전 결격기간은요?', '위반한 날부터 계산하며, 2회 이상이거나 사고·도주가 겹치면 2~5년으로 늘어납니다.'), ('공무원이 면허 취소 중 음주운전을 하면요?', '징계기준상 파면~강등 구간에 해당합니다.')]),
"hit-and-run-injury":("교통사고",[('뺑소니(도주치상) 처벌은요?', '1년 이상 유기징역 또는 500만~3천만 원 벌금이며, 사망 후 도주는 무기 또는 5년 이상 징역입니다.'), ('피해자를 옮겨 놓고 떠나면요?', '피해자를 유기하고 도주한 경우(상해)는 3년 이상 유기징역으로 더 무겁습니다.'), ('뺑소니 면허 결격기간은요?', '사람을 다치게 하고 조치·신고를 하지 않으면 4년, 음주·무면허가 겹치면 5년입니다.')]),
"parked-car-hit-run":("교통사고",[('주차된 차를 긁고 가면 처벌되나요?', '주·정차된 차만 손괴하고 인적사항을 제공하지 않으면 20만 원 이하 벌금·구류·과료 대상이며, 실무상 범칙금으로 끝나는 경우가 많습니다.'), ('아파트 주차장도 해당하나요?', '도로가 아닌 아파트·마트 주차장에서 일어난 사고도 적용됩니다.'), ('더 무겁게 처벌되는 경우는요?', '사람이 타고 있던 차와의 사고나 파편으로 교통 위험을 남긴 경우는 사고후미조치(5년 이하 징역 또는 1천500만 원 이하 벌금)가 문제됩니다.')]),
"failure-to-take-measures":("교통사고",[('사고후미조치는 어떻게 처벌되나요?', '5년 이하 징역 또는 1천500만 원 이하 벌금입니다.'), ('사고가 나면 무엇을 해야 하나요?', '즉시 정차해 사상자를 구호하는 등 필요한 조치를 하고, 피해자에게 인적사항을 제공해야 합니다.'), ('사람이 안 다쳤어도 처벌되나요?', '물건만 손괴된 사고라도 조치가 필요한 상황에서 떠나면 처벌될 수 있습니다.')]),
"road-rage":("교통사고",[('보복운전은 어떤 죄인가요?', '급제동 등으로 겁을 주면 특수협박(7년 이하 징역 또는 1천만 원 이하 벌금), 들이받으면 특수폭행, 다치게 하면 특수상해 등이 적용됩니다.'), ('보복운전 면허 처분은요?', '형사입건되면 벌점 100점(100일 정지), 구속되면 면허가 취소됩니다.'), ('합의하면 끝나나요?', '특수협박·특수폭행 등은 피해자가 처벌을 원하지 않아도 처벌될 수 있어, 합의는 양형에 반영될 뿐입니다.')]),
"school-zone-accident":("교통사고",[('스쿨존 사고 처벌은요?', '어린이 상해는 1년 이상 15년 이하 징역 또는 500만~3천만 원 벌금, 사망은 무기 또는 3년 이상 징역입니다.'), ('민식이법은 언제 적용되나요?', '어린이보호구역에서 안전운전 의무를 위반해 13세 미만 어린이를 다치게 하거나 사망하게 한 경우입니다.'), ('보험에 들어 있으면 처벌 안 받나요?', '보험 가입과 관계없이 형사처벌 대상이며, 보호자와의 합의는 양형에 중요합니다.')]),
"demerit-points":("교통사고",[('벌점 몇 점이면 면허정지인가요?', '처분벌점 40점 이상이면 정지되며 원칙적으로 1점을 1일로 계산합니다.'), ('벌점 몇 점이면 면허취소인가요?', '누산점수가 1년간 121점, 2년간 201점, 3년간 271점 이상이면 취소됩니다.'), ('벌점을 줄일 수 있나요?', '처분벌점이 40점 미만일 때 교육을 마치면 20점이 감경되고, 1년간 무위반·무사고면 40점 미만 벌점은 소멸합니다.')]),
"indecency-criteria":("성범죄",[('어떤 행위가 추행인가요?', '일반인에게 성적 수치심이나 혐오감을 일으키고 성적 자유를 침해하는 행위로, 접촉 부위뿐 아니라 관계·경위·주위 상황을 함께 보고 판단합니다.'), ('강제추행 기준이 바뀌었나요?', '2023년 대법원 전원합의체 판결로 폭행·협박이 저항을 곤란하게 할 정도일 필요가 없고, 불법한 유형력 행사나 공포심을 일으킬 해악의 고지면 충분하다고 바뀌었습니다.'), ('갑자기 만진 것도 강제추행인가요?', '기습추행은 그 행위 자체가 폭행이자 추행이 되어 힘의 세기와 관계없이 강제추행이 됩니다.')]),
"prostitution-limitation":("성범죄",[('성매매 공소시효는 몇 년인가요?', '성인 상대 성매수는 1년 이하 징역 등으로 처벌되어 공소시효가 5년입니다.'), ('여러 번 방문했다면요?', '방문마다 따로 계산하므로 5년이 지난 방문과 지나지 않은 방문을 나눠 봐야 합니다.'), ('상대가 미성년자였다면요?', '아청법상 성매수는 장기 10년이어서 공소시효가 10년이고, 피해자가 성년이 된 날부터 진행하는 특례가 적용될 수 있습니다.')]),
"indecent-assault-settlement":("성범죄",[('강제추행은 합의하면 끝나나요?', '반의사불벌죄가 아니어서 자동으로 끝나지는 않지만, 처벌불원은 처분과 형량에 가장 중요한 사정입니다.'), ('강제추행 합의금은 얼마인가요?', '정해진 금액은 없고 추행의 정도, 관계, 피해 정도, 사건 단계, 가해자 측 사정에 따라 달라집니다.'), ('피해자에게 직접 연락해도 되나요?', '2차 가해나 합의 강요로 평가될 수 있어 대리인을 통해 진행해야 합니다.')]),
"quasi-indecent-assault":("성범죄",[('준강제추행은 어떻게 처벌되나요?', '강제추행과 같이 10년 이하 징역 또는 1천500만 원 이하 벌금입니다.'), ('상대가 기억을 못 하면 심신상실인가요?', '블랙아웃만으로 곧바로 인정되지는 않고, 당시 행동·대화·영상 등으로 실제 판단능력이 없었는지를 봅니다.'), ('상대가 실제로는 깨어 있었다면요?', '대법원은 그런 상태라고 믿고 행위한 경우 불능미수로 처벌할 수 있다고 봅니다.')]),
"rape-sentencing":("성범죄",[('강간죄 형량은요?', '형법상 강간은 3년 이상의 유기징역이며 벌금형이 없습니다.'), ('강간도 집행유예가 나오나요?', '집행유예는 3년 이하 징역일 때만 가능해, 감경 사유가 있어야 검토됩니다.'), ('양형기준상 권고 형량은요?', '일반 강간의 기본 구간은 2년 6월~5년이며, 감경 1년 6월~3년, 가중 4년~7년입니다.')]),
"minor-age-standard":("성범죄",[('아청법상 미성년자는 몇 살까지인가요?', '19세 미만이되, 19세가 되는 해의 1월 1일을 맞은 사람은 제외됩니다.'), ('동의가 있어도 처벌되는 나이는요?', '13세 미만은 누구든지, 13세 이상 16세 미만은 19세 이상인 사람이 간음·추행하면 처벌됩니다.'), ('나이를 몰랐다면요?', '몰랐다면 고의가 부정될 수 있지만, 대화·외모·경위로 알 수 있었는지를 엄격히 봅니다.')]),
"military-sex-crime":("성범죄",[('군인등강제추행은 어떻게 처벌되나요?', '군형법 제92조의3에 따라 1년 이상의 유기징역이며 벌금형이 없습니다.'), ('군인이 민간인을 추행하면요?', '피해자가 민간인이면 군형법이 아니라 형법과 성폭력처벌법이 적용됩니다.'), ('군인 성범죄는 어디서 재판하나요?', '2022년 7월 1일 이후 범한 성폭력범죄는 일반 법원이 재판합니다.')]),
"sex-crime-limitation":("성범죄",[('강제추행 공소시효는요?', '10년 이하 징역 등으로 처벌되어 공소시효가 10년입니다.'), ('미성년자 피해 사건은요?', '피해자가 성년이 된 날부터 공소시효가 진행하고, 13세 미만·장애인 대상 강간 등은 공소시효가 없습니다.'), ('DNA 증거가 있으면요?', '강간 등 일정한 범죄는 과학적 증거가 있으면 공소시효가 10년 연장됩니다.')]),
"sex-crime-false-report":("성범죄",[('성범죄가 무혐의면 무고인가요?', '무혐의는 유죄를 증명하지 못했다는 뜻일 뿐이어서, 신고가 허위였고 신고자가 그것을 알았다는 점을 따로 증명해야 합니다.'), ('무고죄 처벌은요?', '10년 이하 징역 또는 1천500만 원 이하 벌금입니다.'), ('맞고소하면 바로 수사하나요?', '성폭력 수사매뉴얼상 원칙적으로 성폭력 사건 판단이 나올 때까지 무고 수사는 미뤄집니다.')]),
"obscene-distribution":("성범죄",[('음란물 유포죄 처벌은요?', '정보통신망법에 따라 1년 이하 징역 또는 1천만 원 이하 벌금입니다.'), ('토렌트로 받기만 해도 유포인가요?', '받는 동안 자동으로 올라가는 구조여서 유포가 문제될 수 있으며, 그 사실을 알았는지가 쟁점입니다.'), ('불법촬영물이었다면요?', '성폭력처벌법상 촬영물 반포로 7년 이하 징역 또는 5천만 원 이하 벌금이 적용될 수 있습니다.')]),
"tongmaeum-settlement":("성범죄",[('통매음은 합의하면 끝나나요?', '반의사불벌죄가 아니어서 자동으로 끝나지는 않지만, 처벌불원은 기소유예와 벌금을 가르는 중요한 사정입니다.'), ('사과 메시지를 보내도 되나요?', '추가 피해나 스토킹으로 평가될 수 있어 직접 연락은 피해야 합니다.'), ('합의 금액은 어떻게 정해지나요?', '메시지 수위, 횟수와 기간, 관계, 피해 정도, 사건 단계에 따라 달라집니다.')]),
"indecent-assault-injury":("성범죄",[('강제추행치상은 어떻게 처벌되나요?', '형법 제301조에 따라 무기 또는 5년 이상의 징역입니다.'), ('작은 멍도 상해인가요?', '찰과상도 상해로 인정된 판례가 있지만, 저절로 낫는 아주 경미한 상처는 상해로 보지 않은 판례도 있습니다.'), ('정신적 피해도 상해가 되나요?', '외상 후 스트레스 장애처럼 정신적 기능에 장애가 생긴 경우도 상해가 될 수 있습니다.')]),
"statutory-rape":("성범죄",[('미성년자의제강간은 동의가 있어도 처벌되나요?', '13세 미만, 또는 13세 이상 16세 미만을 상대로 한 19세 이상의 간음은 동의와 관계없이 강간의 예로 처벌됩니다.'), ('형량은요?', '간음이면 강간죄와 같이 3년 이상의 유기징역이며 벌금형이 없습니다.'), ('헌법재판소 판단은요?', '헌법재판소는 2024년 6월 형법 제305조 제2항을 전원 일치로 합헌 결정했습니다.')]),
"digital-sex-crime-types":("성범죄",[('디지털 성범죄에는 어떤 것이 있나요?', '불법촬영과 유포, 딥페이크, 촬영물 협박, 아동·청소년 성착취물, 통매음, 성착취 목적 대화 등이 있습니다.'), ('보기만 해도 처벌되나요?', '불법촬영물, 딥페이크, 아동·청소년 성착취물은 소지·시청도 처벌됩니다.'), ('성인 피해 사건도 위장수사를 하나요?', '2025년 6월부터 성인 대상 디지털 성범죄에도 신분비공개·위장수사가 가능해졌습니다.')]),
}
